const incoming = $input.first().json || {};
const isWebhook = Object.prototype.hasOwnProperty.call(incoming, 'body');
const body = isWebhook ? (incoming.body || {}) : {};
if (isWebhook && (!body.siren || !body.email || body.bounce_type !== 'recipient_not_found')) {
  throw new Error('Le webhook de remplacement attend siren, email et bounce_type=recipient_not_found.');
}
return [{
  json: {
    mode: isWebhook ? 'replacement' : 'daily',
    cible: isWebhook ? 1 : 20,
    target: isWebhook ? 1 : 20,
    siren: isWebhook ? String(body.siren).replace(/\D/g, '') : null,
    email: isWebhook ? String(body.email).trim().toLowerCase() : null,
    debut: new Date().toISOString()
  }
}];

// F : collecte quotidienne d'entreprises titulaires de marchés publics (BOAMP), enrichies
// sans API payante : annuaire officiel (recherche-entreprises.api.gouv.fr) + site web de
// l'entreprise (deviné à partir du nom, sinon moteur de recherche) + email publié sur ce site.
// Dédoublonnage par SIREN. Version 3 : lecture des avis eForms, critères assouplis,
// budget de temps, compteur des raisons de rejet.
const ctx = $('Définir le traitement').last().json;
const inputRows = $input.all().map(i => i.json || {});
const target = Number(ctx.target || 20);
const mode = ctx.mode || 'daily';
const debut = ctx.debut || new Date().toISOString();
if (inputRows.find(x => x.error)) return [{ json: { debut, mode, cible: target, avis_lus: 0, candidats_vus: 0, nouvelles: [], sorties: 0, rejets: {}, erreur: 'Lecture de Supabase impossible ; arrêt pour éviter les doublons.', statut: 'erreur' } }];
const known = new Set(inputRows.map(x => String(x.siren || '').replace(/\D/g, '')).filter(Boolean));

// ===== RÉGLAGES =====
const BUDGET_MS = 230000;        // n8n coupe un bloc de code après 5 min : on s'arrête avant, avec ce qui est trouvé
const PARALLELE = 4;             // entreprises enrichies en même temps
const MAX_AVIS = 3000;           // avis d'attribution lus au maximum
// ====================
const FIN = Date.now() + BUDGET_MS;
const tempsRestant = () => FIN - Date.now();
const BOAMP = 'https://boamp-datadila.opendatasoft.com/api/explore/v2.1/catalog/datasets/boamp/records';
const GOV = 'https://recherche-entreprises.api.gouv.fr/search';
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';
const pause = ms => new Promise(r => (typeof setTimeout === 'function' ? setTimeout(r, ms) : r()));
const arr = x => Array.isArray(x) ? x : (x == null ? [] : [x]);
const chiffres = x => String(x || '').replace(/\D/g, '');
const norm = s => String(s || '').toLocaleLowerCase('fr').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const rejets = {};
const diag = { sites_devines_testes: 0, sites_devines_repondus: 0, sites_repondus_non_confirmes: 0, recherches_web: 0, recherches_avec_resultats: 0, exemple_non_confirme: null, derniere_erreur: null };
const rejeter = raison => { rejets[raison] = (rejets[raison] || 0) + 1; return null; };

// n8n n'expose pas l'objet URL dans les blocs de code : petit analyseur d'adresse maison
const lireUrl = s => {
  const m = String(s || '').trim().match(/^(https?):\/\/([^\/?#:]+)(:\d+)?([^#]*)/i);
  if (!m) return null;
  const hostname = m[2].toLowerCase(), origin = m[1].toLowerCase() + '://' + hostname + (m[3] || '');
  return { hostname, origin, href: origin + (m[4] || '/') };
};
// ---------- Pages web ----------
const getPage = async (url, ms = 8000) => {
  if (tempsRestant() < 5000) return '';
  try {
    const x = await this.helpers.httpRequest({ method: 'GET', url, timeout: ms, headers: { 'User-Agent': UA, 'Accept-Language': 'fr-FR,fr;q=0.9' } });
    if (typeof x === 'string') return x;
    if (x && typeof Buffer !== 'undefined' && Buffer.isBuffer(x)) return x.toString('utf8');
    return x && typeof x === 'object' ? JSON.stringify(x) : String(x || '');
  } catch (e) { diag.derniere_erreur_page = String(e && e.message || e).slice(0, 200); return ''; }
};
const emailRe = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i;
const emailInterdit = /noreply|no-reply|ne-pas-repondre|example\.|sentry|wixpress|godaddy|domain\.|votre-?email|email@|nom@|exemple|\.(png|jpe?g|gif|webp|svg)$/i;
const extraireEmails = html => {
  const s = String(html || '').replace(/&#64;|&#x40;|\[at\]|\(at\)| arobase /gi, '@');
  const mailto = [...s.matchAll(/mailto:([^"'?\s>]+)/gi)].map(m => { try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; } });
  const texte = s.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [];
  return [...new Set([...mailto, ...texte].map(x => x.trim().toLowerCase()))].filter(x => emailRe.test(x) && !emailInterdit.test(x));
};
// préfère une adresse du domaine du site, puis une adresse « contact/info »
const choisirEmail = (emails, host) => {
  const dom = String(host || '').replace(/^www\./, '');
  const duSite = emails.filter(e => dom && e.endsWith('@' + dom));
  const liste = duSite.length ? duSite : emails;
  return liste.find(e => /^(contact|info|accueil|direction|commercial|devis)@/.test(e)) || liste[0] || null;
};
const ANNUAIRES = /pappers|societe\.com|annuaire|pagesjaunes|infogreffe|verif\.com|manageo|kompass|linkedin|facebook|instagram|youtube|wikipedia|boamp|marches-publics|achatpublic|aws-achat|klekoon|e-marchespublics|doctrine|bfmtv|lefigaro|indeed|google|bing|duckduckgo|mappy|118712|corporama|score3|entreprises\.lefigaro|dirigeants\.bfmtv/i;
// la page appartient-elle bien à l'entreprise ? (SIREN présent, ou nom + code postal / commune)
const FORMES = new Set(['sarl', 'sas', 'sasu', 'eurl', 'sa', 'sci', 'snc', 'ets', 'etablissements', 'entreprise', 'societe', 'ste', 'groupe', 'france', 'et', 'de', 'des', 'du', 'la', 'le', 'les', 'fils', 'cie', 'compagnie']);
const pageConfirmee = (html, e) => {
  const brut = String(html || ''); if (brut.length < 300) return false;
  if (chiffres(brut.replace(/\s/g, '')).includes(e.siren) || brut.replace(/[\s.]/g, '').includes(e.siren)) return true;
  const t = norm(brut.slice(0, 400000));
  const motsNom = norm(e.nom).split(' ').filter(w => w.length > 2 && !FORMES.has(w));
  const nomOk = motsNom.length && motsNom.filter(w => t.includes(w)).length >= Math.min(2, motsNom.length);
  const dep2 = String(e.cp || '').slice(0, 2);
  const lieuOk = (e.cp && t.includes(e.cp)) || (e.commune && t.includes(norm(e.commune))) || (dep2 && new RegExp('\\b' + dep2 + '\\d{3}\\b').test(t));
  return nomOk && lieuOk;
};
// sites probables à partir du nom : « Martin Paysages SARL » -> martinpaysages.fr, martin-paysages.fr, …
const sitesDevines = nom => {
  const mots = norm(nom).split(' ').filter(w => w && !FORMES.has(w));
  if (!mots.length || mots.join('').length < 4) return [];
  const bases = [...new Set([mots.join(''), mots.join('-'), mots.slice(0, 2).join(''), mots.slice(0, 2).join('-')])].filter(b => b.length >= 4 && b.length <= 40);
  return bases.flatMap(b => ['https://www.' + b + '.fr', 'https://www.' + b + '.com']).slice(0, 6);
};
// moteurs de recherche (souvent limités pour les robots : utilisés en dernier recours)
const rechercheWeb = async q => {
  const essais = [
    ['https://html.duckduckgo.com/html/?q=' + encodeURIComponent(q), /<a[^>]+class="result__a"[^>]+href="([^"]+)"/gi],
    ['https://www.bing.com/search?setlang=fr&cc=FR&q=' + encodeURIComponent(q), /<li class="b_algo"[\s\S]*?<a[^>]+href="(https?:[^"]+)"/gi]
  ];
  for (const [url, re] of essais) {
    diag.recherches_web++;
    const html = await getPage(url, 10000);
    const liens = [...html.matchAll(re)].map(m => {
      try { const brut = decodeURIComponent((m[1].match(/[?&]uddg=([^&]+)/) || [])[1] || m[1]); return lireUrl(brut.startsWith('http') ? brut : 'https:' + brut); } catch (e) { return null; }
    }).filter(u => u && !ANNUAIRES.test(u.hostname));
    if (liens.length) { diag.recherches_avec_resultats++; return liens.slice(0, 3).map(u => u.origin); }
  }
  return [];
};
const trouverSite = async e => {
  for (const url of sitesDevines(e.nom)) {
    if (tempsRestant() < 8000) break;
    diag.sites_devines_testes++;
    const html = await getPage(url, 6000);
    if (html.length > 300) diag.sites_devines_repondus++;
    if (pageConfirmee(html, e)) return { origin: lireUrl(url).origin, html, via: 'nom' };
    if (html.length > 300) { diag.sites_repondus_non_confirmes++; if (!diag.exemple_non_confirme) diag.exemple_non_confirme = e.nom + ' -> ' + url; }
  }
  const q = `"${e.nom}" ${e.commune || e.cp || ''}`.trim();
  for (const origin of await rechercheWeb(q)) {
    const html = await getPage(origin, 8000);
    if (pageConfirmee(html, e)) return { origin, html, via: 'recherche' };
  }
  return null;
};
// ---------- Vérification MX : le domaine de l'adresse peut-il recevoir des mails ? ----------
// true = oui, false = non (pas de serveur mail, domaine inexistant), null = DNS injoignable (on ne rejette pas)
const mxCache = {};
const domaineRecoitMails = async domaine => {
  domaine = String(domaine || '').toLowerCase().trim();
  if (!domaine) return false;
  if (domaine in mxCache) return mxCache[domaine];
  let ok = null;
  for (const url of ['https://dns.google/resolve', 'https://cloudflare-dns.com/dns-query']) {
    try {
      let rep = await this.helpers.httpRequest({ method: 'GET', url, qs: { name: domaine, type: 'MX' }, headers: { Accept: 'application/dns-json' }, json: true, timeout: 6000 });
      if (typeof rep === 'string') rep = JSON.parse(rep);
      if (rep.Status === 3) { ok = false; break; }                       // domaine inexistant
      if (rep.Status !== 0) continue;
      const mx = (rep.Answer || []).filter(a => a.type === 15).map(a => String(a.data || '').trim());
      ok = mx.length > 0 && !mx.every(d => /^0\s+\.?$/.test(d));         // "0 ." = le domaine refuse tout mail
      break;
    } catch (e) { /* on essaie l'autre résolveur */ }
  }
  if (ok === null) diag.mx_injoignable = (diag.mx_injoignable || 0) + 1;
  mxCache[domaine] = ok;
  return ok;
};

const trouverEmail = async site => {
  const host = lireUrl(site.origin).hostname;
  let emails = extraireEmails(site.html);
  if (!emails.length) for (const chemin of ['/contact', '/contact/', '/nous-contacter', '/mentions-legales', '/mentions-legales/', '/contact.html']) {
    if (tempsRestant() < 5000) break;
    emails = extraireEmails(await getPage(site.origin + chemin, 7000));
    if (emails.length) break;
  }
  const publie = choisirEmail(emails, host);
  if (publie) return { email: publie, type: 'publie' };
  return { email: 'contact@' + host.replace(/^www\./, ''), type: 'deduit' };   // site confirmé, adresse à vérifier à la main
};

// ---------- Avis d'attribution BOAMP (ancien format et eForms) ----------
// On prend tous les SIRET présents dans l'avis, sauf ceux des organismes publics
// (SIREN commençant par 1 ou 2 : État, collectivités, établissements publics).
const candidatsDeLAvis = r => {
  let d = r.donnees || r.DONNEES || {};
  if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { d = {}; } }
  const sirets = new Set();
  const parcourir = o => {
    if (o == null) return;
    if (typeof o === 'string' || typeof o === 'number') {
      for (const m of String(o).matchAll(/(?<!\d)(\d{3}\s?\d{3}\s?\d{3}\s?\d{5})(?!\d)/g)) sirets.add(m[1].replace(/\s/g, ''));
      return;
    }
    if (typeof o === 'object') for (const v of Object.values(o)) parcourir(v);
  };
  parcourir(d); parcourir(r.titulaire); parcourir(r.siret);
  const acheteur = chiffres(r.siret_acheteur || r.code_siret_acheteur || '').slice(0, 9);
  const dep = arr(r.code_departement || r.code_departement_prestation)[0];
  const sourceUrl = r.url_avis || (r.idweb ? 'https://www.boamp.fr/pages/avis/?idweb=' + encodeURIComponent(r.idweb) : null);
  return [...sirets].filter(s => /^[3-9]/.test(s) && s.slice(0, 9) !== acheteur).map(siret => ({
    siret, siren: siret.slice(0, 9), dep_marche: dep ? String(dep).padStart(2, '0') : null,
    source_url: sourceUrl, source_marche: String(r.objet || '').slice(0, 500) || null,
    date_attribution: String(r.dateparution || '').slice(0, 10) || null,
    montant_marche: Number(r.montant || r.valeur || 0) || null
  }));
};

// ---------- Annuaire officiel ----------
const TRANCHES = { '00': null, NN: null, '01': '1-9', '02': '1-9', '03': '1-9', '11': '10-24', '12': '20-49', '21': '50-249', '22': '50-249', '31': '50-249', '32': '250-999', '41': '250-999', '42': '1000+', '51': '1000+', '52': '1000+', '53': '1000+' };
const annuaire = async c => {
  for (let essai = 0; essai < 2; essai++) {
    try {
      const rep = await this.helpers.httpRequest({ method: 'GET', url: GOV, qs: { q: c.siret, page: 1, per_page: 3 }, json: true, timeout: 10000 });
      return (rep.results || []).find(x => x.siren === c.siren) || null;
    } catch (e) { await pause(1200); }   // limite de 7 requêtes/s : on réessaie une fois
  }
  return null;
};

const enrichir = async c => {
  const g = await annuaire(c);
  if (!g) return rejeter('introuvable_annuaire');
  if (g.etat_administratif && g.etat_administratif !== 'A') return rejeter('entreprise_fermee');
  if (g.complements?.est_service_public || /^7/.test(String(g.nature_juridique || ''))) return rejeter('organisme_public');
  const siege = g.siege || {};
  const effectif = TRANCHES[String(g.tranche_effectif_salarie || siege.tranche_effectif_salarie || 'NN')] ?? null;
  if (effectif === '1000+') return rejeter('trop_grande');
  const naf = g.activite_principale || siege.activite_principale || null;
  const nafLib = g.libelle_activite_principale || siege.libelle_activite_principale || null;
  const cp = String(siege.code_postal || '').trim();
  let dep = cp.slice(0, 2) || c.dep_marche;
  if (dep === '20') dep = cp.startsWith('201') ? '2A' : '2B';
  const dirigeants = arr(g.dirigeants).filter(x => x && x.type_dirigeant !== 'personne morale' && (x.nom || x.prenoms));
  const dir = dirigeants[0];
  const e = { siren: c.siren, nom: g.nom_complet || g.nom_raison_sociale || '', cp, commune: siege.libelle_commune || '' };
  if (!e.nom) return rejeter('introuvable_annuaire');
  const site = await trouverSite(e);
  if (!site) return rejeter('site_web_introuvable');
  const { email, type } = await trouverEmail(site);
  if (!email) return rejeter('email_introuvable');
  const mxOk = await domaineRecoitMails(email.split('@')[1]);
  if (mxOk === false) { if (!diag.exemple_sans_mx) diag.exemple_sans_mx = email; return rejeter('domaine_sans_serveur_mail'); }
  return {
    rang: effectif === '1-9' || effectif === null ? 0 : (effectif === '250-999' ? 2 : 1),
    lead: {
      siret: c.siret, siren: c.siren, nom: String(e.nom).slice(0, 300), ville: e.commune || null, departement: dep || null,
      secteur: [naf, nafLib].filter(Boolean).join(' — ').slice(0, 300) || null,
      domaine_activite: String(nafLib || c.source_marche || '').slice(0, 500) || null,
      effectif_tranche: effectif, dirigeant: dir ? [dir.prenoms, dir.nom].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim().slice(0, 200) : null,
      email, email_type: type, email_statut: type === 'deduit' ? 'format_domaine_verifies_a_confirmer' : 'publie',
      email_valide: type === 'publie',
      site_web: site.origin, source_type: 'BOAMP', source_url: c.source_url || site.origin,
      source_marche: c.source_marche, date_attribution: c.date_attribution, montant_marche: c.montant_marche,
      statut: 'à contacter', trouve_le: new Date().toISOString()
    }
  };
};

// ---------- Boucle principale ----------
const trouves = [];
let avisLus = 0, candidatsVus = 0, error = null, arret = null;
const assez = () => trouves.filter(t => t.lead.email_valide).length >= target;
const vus = new Set();
try {
  let offset = 0, filtre = 'nature="ATTRIBUTION"', file = [];
  while (!assez() && avisLus < MAX_AVIS) {
    if (tempsRestant() < 15000) { arret = 'temps'; break; }
    let rep;
    try {
      rep = await this.helpers.httpRequest({ method: 'GET', url: BOAMP, qs: { where: filtre, order_by: 'dateparution desc', limit: 100, offset }, json: true, timeout: 30000 });
    } catch (e) {
      if (filtre === 'nature="ATTRIBUTION"') { filtre = 'nature_libelle like "attribution"'; offset = 0; continue; }
      throw e;
    }
    const res = rep.results || [];
    if (!res.length) break;
    avisLus += res.length; offset += res.length;
    for (const r of res) for (const c of candidatsDeLAvis(r)) {
      if (known.has(c.siren)) { rejeter('deja_en_base'); continue; }
      if (vus.has(c.siren)) continue;
      vus.add(c.siren); file.push(c);
    }
    while (file.length && !assez() && tempsRestant() > 15000) {
      const lot = file.splice(0, PARALLELE);
      candidatsVus += lot.length;
      const res2 = await Promise.all(lot.map(c => enrichir(c).catch(err => { diag.derniere_erreur = String(err && (err.stack || err.message) || err).slice(0, 300); return rejeter('erreur_technique'); })));
      for (const x of res2) if (x && !known.has(x.lead.siren)) { known.add(x.lead.siren); trouves.push(x); }
    }
    if (tempsRestant() <= 15000) { arret = 'temps'; break; }
  }
} catch (e) { error = 'BOAMP : ' + String(e.message || e).slice(0, 250); }

// emails publiés d'abord, puis petites entreprises d'abord
const nouvelles = trouves.sort((a, b) => (b.lead.email_valide - a.lead.email_valide) || (a.rang - b.rang)).slice(0, target + 10).map(x => x.lead);
const valides = nouvelles.filter(x => x.email_valide).length;
return [{
  json: {
    debut, mode, cible: target, avis_lus: avisLus, candidats_vus: candidatsVus,
    nouvelles, sorties: nouvelles.length, emails_valides: valides, rejets, diag, arret, erreur: error,
    statut: error && !nouvelles.length ? 'erreur' : valides >= target ? 'ok' : (nouvelles.length ? 'partiel' : 'vide')
  }
}];

const c = $('Collecter et qualifier les entreprises').last().json;
const save = $input.all().map(x => x.json || {}).filter(x => x.error);
const LIB = { deja_en_base: 'déjà en base', introuvable_annuaire: 'introuvable dans l\'annuaire', entreprise_fermee: 'fermée', organisme_public: 'organisme public',
  trop_grande: 'trop grande', site_web_introuvable: 'site web introuvable', email_introuvable: 'email introuvable', erreur_technique: 'erreur technique', domaine_sans_serveur_mail: 'domaine sans serveur mail' };
const rej = Object.entries(c.rejets || {}).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${v} ${LIB[k] || k}`).join(', ');
let statut = c.statut || 'vide';
if (!['ok', 'vide', 'erreur', 'en_cours'].includes(statut)) statut = (c.sorties || 0) > 0 ? 'ok' : 'vide';   // 'partiel' refusé par la table agent_runs
let message;
if (save.length) { statut = 'erreur'; message = 'Écriture Supabase impossible (lancer supabase_prospection.sql) : ' + JSON.stringify(save[0].error).slice(0, 250); }
else message = [c.erreur,
  `${c.emails_valides || 0} entreprise(s) avec email publié, ${(c.sorties || 0) - (c.emails_valides || 0)} avec email à vérifier, sur ${c.candidats_vus || 0} candidates (${c.avis_lus || 0} avis lus).`,
  rej ? 'Écartées : ' + rej + '.' : '',
  c.diag ? `Sites devinés : ${c.diag.sites_devines_testes} essayés, ${c.diag.sites_devines_repondus} ont répondu, ${c.diag.sites_repondus_non_confirmes} écartés (pas la bonne entreprise). Recherche web : ${c.diag.recherches_avec_resultats}/${c.diag.recherches_web} avec résultats.` : '',
  c.diag && c.diag.derniere_erreur ? 'Erreur : ' + c.diag.derniere_erreur.split('\n')[0] : '', c.arret === 'temps' ? 'Arrêt au bout de 4 min (limite n8n) : la suite au prochain passage.' : ''].filter(Boolean).join(' ');
return [{ json: { agent: 'F-commercial', debut: c.debut, fin: new Date().toISOString(), statut, entrees: c.avis_lus, sorties: c.emails_valides || 0,
  details: { mode: c.mode, cible: c.cible, candidats_vus: c.candidats_vus, enregistrees: c.sorties, emails_valides: c.emails_valides, rejets: c.rejets || {}, diag: c.diag || null }, message } }];
